/**
 * The one form every resource-module operation takes: a Distilled operation
 * called with the resource's path ids first, then the rest of its input,
 * then the caller's {@link RequestOptions}, through the {@link StripeHttp}
 * client in context.
 *
 * The resource modules (`Customer.ts`, `Invoice.ts`, …) are generated by
 * `scripts/generate-resources.ts`, one `operation(…)` per Distilled operation
 * on the resource, each annotated with its typed signature.
 *
 * @module
 */

import * as Arr from "effect/Array";
import * as Effect from "effect/Effect";
import * as Predicate from "effect/Predicate";
import * as Record from "effect/Record";
import { PaymentInvalidRequestError, type PaymentsError } from "@thomasfosterau/effect-payments";
import { type Method, type Operation, type RequestOptions, StripeHttp } from "../StripeHttp.js";

/** What an operation's call needs to know of its Distilled operation. */
export interface Route {
  /** The operation's HTTP method (a `POST`, or a `/v2` `DELETE`, gets a generated key when it may be retried). */
  readonly method: Method;
  /** The path template, for the message of a refused id. */
  readonly path: string;
  /** The input members that are path ids, in the order they appear in the path. */
  readonly ids: ReadonlyArray<string>;
  /** Whether the operation takes input beyond its path ids (`params`). */
  readonly params: boolean;
  /** Whether the request goes to the file-uploads origin (`POST /v1/files`). */
  readonly upload?: boolean | undefined;
}

/**
 * The fields of a caller's {@link RequestOptions}, and nothing else: an
 * options object from untyped code must not be able to set `upload`.
 */
const pickOptions = (options: RequestOptions | undefined): RequestOptions => ({
  idempotencyKey: options?.idempotencyKey,
  stripeAccount: options?.stripeAccount,
  apiVersion: options?.apiVersion,
});

/**
 * Refuse a path id that is not a non-empty string before anything is sent:
 * Distilled would splice `""` into the path (`/v1/customers/` is the list),
 * and an `undefined` from untyped code would leave the template in it.
 */
const checkIds = (
  route: Route,
  values: ReadonlyArray<unknown>,
): Effect.Effect<void, PaymentInvalidRequestError> => {
  const invalid = values.findIndex((value) => !Predicate.isString(value) || value === "");
  return invalid === -1
    ? Effect.void
    : Effect.fail(
        new PaymentInvalidRequestError({
          message: `Path segment ${invalid + 1} of ${route.path} must be a non-empty string`,
          param: route.ids[invalid],
        }),
      );
};

/** The params argument as an object to spread: absent, or anything but an object, is none. */
const paramsOf = (value: unknown): Readonly<Record<string, unknown>> =>
  Predicate.isObject(value) ? value : {};

/** A file part of an upload: sent as itself, never flattened. */
const isFile = (value: unknown): boolean =>
  value instanceof Blob || value instanceof Uint8Array || value instanceof ArrayBuffer;

/** One upload parameter as Stripe's bracketed form fields (`file_link_data[create]`). */
const fieldsOf = (key: string, value: unknown): ReadonlyArray<readonly [string, unknown]> => {
  const entries = Array.isArray(value)
    ? value.map((item, index) => [String(index), item] as const)
    : isFile(value) || !Predicate.isObject(value)
      ? undefined
      : Record.toEntries(value);
  if (entries === undefined) return [[key, value]];
  return entries.flatMap(([name, item]) => fieldsOf(`${key}[${name}]`, item));
};

/**
 * An upload's params with every nested member flattened into bracketed keys.
 * Distilled's multipart encoder sends a nested object or array as one JSON
 * part (`file_link_data={"create":true}`), which Stripe does not read; a flat
 * key it does not know it sends as a text part, as Stripe expects.
 */
const flattenUpload = (
  params: Readonly<Record<string, unknown>>,
): Readonly<Record<string, unknown>> =>
  Record.fromEntries(Arr.flatMap(Record.toEntries(params), ([key, value]) => fieldsOf(key, value)));

/**
 * One resource-module operation: `(…ids, params?, options?)` calling
 * `operation` with `{ …params, [id]: value }`. `F` is the signature the
 * generated module annotates the export with.
 */
export const operation = <F>(distilled: Operation<never, unknown, unknown>, route: Route): F => {
  const call = (
    ...args: ReadonlyArray<unknown>
  ): Effect.Effect<unknown, PaymentsError, StripeHttp> => {
    const ids = args.slice(0, route.ids.length);
    const params = route.params ? args[route.ids.length] : undefined;
    // SAFETY: the trailing argument is `RequestOptions` by the generated
    // signature; `pickOptions` reads only its three fields.
    const options = args[route.ids.length + (route.params ? 1 : 0)] as RequestOptions | undefined;
    const given = paramsOf(params);
    const input = Record.fromEntries([
      ...Record.toEntries(route.upload ? flattenUpload(given) : given),
      ...route.ids.map((name, index) => [name, ids[index]] as const),
    ]);
    return Effect.andThen(
      checkIds(route, ids),
      Effect.flatMap(StripeHttp, (http) =>
        // SAFETY: `input` is the operation's input, assembled from the
        // generated signature's ids and params; `call` passes it on unread.
        http.call(route.method, distilled, input as never, {
          ...pickOptions(options),
          upload: route.upload,
        }),
      ),
    );
  };
  // SAFETY: `call` is the generated signature `F` at runtime — ids, then
  // params when the operation takes any, then options — resolving to the
  // response JSON, which Distilled's output type describes (unchecked:
  // lenient validation; see `StripeHttp`).
  return call as F;
};
